package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTeDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("రూస్టర్ లేదా గాడిద వినడం", "ఓ అల్లాహ్, నేను నీ అనుగ్రహం (రూస్టర్) గురించి అడుగుతున్నాను.-నేను శాపగ్రస్తుడైన (గాడిద) షైతాన్ నుండి అల్లాహ్ ఆశ్రయాన్ని కోరుతున్నాను.", "ఒక రూస్టర్ అల్లాహ్ అనుగ్రహం కోసం అడగడం విన్నప్పుడు, ఒక గాడిద బ్రాయ్ విన్నప్పుడు షైతాన్ నుండి ఆశ్రయం పొందండి.", "రూస్టర్ ఒక దేవదూతను చూస్తుంది మరియు గాడిద ఒక దెయ్యాన్ని చూస్తుంది."),
        "dua_something_liked" to DuaText("ప్రశంసనీయమైనదాన్ని చూడటం (చెడు కంటికి వ్యతిరేకంగా)", "అల్లాహ్ ఏమి కోరుకుంటున్నాడో అది. అల్లాహ్, దానిని ఆశీర్వదించండి.", "ఎవరికైనా చెందిన ప్రశంసనీయమైనదాన్ని చూసినప్పుడు, ఆశీర్వాదం కోసం ప్రార్థించండి.", "ఆశీర్వాదం కోసం ప్రార్థించడం చెడు కన్ను నిరోధిస్తుంది."),
        "dua_sell_buy_debt_repaid" to DuaText("రుణాన్ని తిరిగి చెల్లించేటప్పుడు", "అల్లాహ్ మిమ్మల్ని మీ కుటుంబంలో మరియు మీ సంపదలో ఆశీర్వదించుగాక.", "రుణాన్ని తిరిగి చెల్లించేటప్పుడు రుణదాత కోసం.", "రుణానికి తిరిగి చెల్లింపు అంటే కృతజ్ఞత మరియు తిరిగి చెల్లింపు."),
        "dua_talbiyah" to DuaText("తల్బియా", "నేను ఇక్కడే ఉన్నాను, ఓ అల్లాహ్, ఇక్కడే ఉన్నాను. ఇక్కడే ఉన్నాను, మీకు భాగస్వామి లేరు, ఇక్కడే ఉన్నాను. ఖచ్చితంగా ప్రశంసలు, ఆశీర్వాదాలు, ఆధిపత్యం అన్నీ మీవే. మీకు భాగస్వామి లేరు.", "ఇహ్రామ్ లోకి ప్రవేశించిన తర్వాత బిగ్గరగా.", "హజ్ మరియు ఉమ్రా యొక్క చిహ్నం."),
        "dua_yamani_hajar" to DuaText("రుక్న్ యమని మరియు హజార్ అస్వాడ్ మధ్య", "మా ప్రభూ, మాకు ఈ లోకంలో మంచిని, పరలోకంలో మంచిని ప్రసాదించండి, అగ్ని శిక్ష నుండి మమ్మల్ని రక్షించండి.", "తవాఫ్లో, యెమెన్ కార్నర్ మరియు బ్లాక్ స్టోన్ మధ్య.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ స్థలంలో తవాఫ్ లో దీనిని పఠించారు."),
        "dua_safa_marwa" to DuaText("సఫా మరియు మార్వా గురించి", "అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడటానికి హక్కు లేదు, ఒంటరిగా, భాగస్వామి లేకుండా. ఆధిపత్యం అతనిదే, ప్రశంసలు అతనివే, అన్ని విషయాలపై అధికారం అతనిదే. అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడరు. అతను తన వాగ్దానాన్ని నెరవేర్చాడు, తన సేవకుడికి సహాయం చేశాడు మరియు సమాఖ్యలను ఓడించాడు.", "సఫా ఎక్కి, కిబ్లాకు ఎదురుగా (మూడు సార్లు).", "సఫా మరియు మార్వా మీద ప్రవక్త యొక్క ధిక్ర్."),
        "dua_arafah" to DuaText("అరాఫా రోజు యొక్క ఉత్తమ దువా", "అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడటానికి హక్కు లేదు, ఒంటరిగా, భాగస్వామి లేకుండా. ఆధిపత్యం మరియు ప్రశంసలు అతనివే, మరియు అతను అన్ని విషయాలపై అధికారం కలిగి ఉన్నాడు.", "అరాఫా రోజు-ఉత్తమ దుఆ.", "అరాఫా రోజు యొక్క దుఆ ఉత్తమ దుఆ, మరియు ఉత్తమ పదాలు ఇవి."),
        "dua_takbeer_tashreeq" to DuaText("తక్బీర్-ఎ-తష్రీక్", "అల్లాహ్ గొప్పవాడు, అల్లాహ్ గొప్పవాడు. అల్లాహ్ తప్ప దేవుడు లేడు. అల్లాహ్ గొప్పవాడు, అల్లాహ్ గొప్పవాడు, మరియు అన్ని ప్రశంసలు అల్లాహ్ కోసం.", "9 ధుల్-హిజ్జా యొక్క ఫజ్ర్ నుండి 13 ధుల్-హిజ్జా యొక్క అస్ర్ వరకు ప్రతి తప్పనిసరి ప్రార్థన తరువాత.", "అలీ మరియు ఇబ్న్ మసూద్ (రా) నుండి నివేదించబడింది-హనాఫీల ప్రకారం వాజిబ్."),
        "dua_zamzam" to DuaText("జంజాం తాగడం", "ఓ అల్లాహ్, నేను ప్రయోజనకరమైన జ్ఞానం, సమృద్ధిగా ఆహారం మరియు ప్రతి వ్యాధి నుండి నివారణ కోసం నిన్ను అడుగుతున్నాను.", "జంజాం తాగుతున్నప్పుడు, మీరు కోరుకున్నదానికి దుఆ చేయండి.", "జంజాం అనేది అది తాగిన దేనికైనా (ఇబ్న్ మాజా 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("సృష్టి గురించి ఆలోచించడం", "మా ప్రభూ, నీవు ఇదంతా వృథా గా సృష్టించలేదు. మహిమగలవాడవు నీవు, కాబట్టి మమ్మల్ని అగ్ని శిక్ష నుండి రక్షించు.", "ఆకాశాలు మరియు భూమి యొక్క సృష్టి గురించి ఆలోచించే వారి దుఆ.", "అవగాహన గల వ్యక్తుల దుఆ (ఉలుల్-అల్బాబ్)."),
        "dua_q_sami_na_munadiyan" to DuaText("విశ్వాసానికి పిలుపు ఇచ్చేవాడిని మేము విన్నాము", "మా ప్రభూ, ఒక వ్యక్తి'నీ ప్రభువును నమ్ము'అని పిలవడం మేము విన్నాము, మరియు మేము విశ్వసించాము. మా ప్రభూ, మా పాపాలను మాకు క్షమించు, మా దుర్మార్గాలను మా నుండి తొలగించు, మరియు మమ్మల్ని నీతిమంతులతో పాటు మరణానికి గురిచేయుము.", "విశ్వాసానికి మరియు నీతిమంతుల మధ్య మరణించడానికి ఒక దుఆ.", "క్షమాపణ మరియు మంచి ముగింపు కోసం ఒక దుఆ."),
        "dua_q_atina_ma_waadtana" to DuaText("మీరు వాగ్దానం చేసిన దాన్ని మాకు ఇవ్వండి.", "మా ప్రభూ, నీ దూతల ద్వారా మాకు వాగ్దానం చేసిన దానిని మాకు ప్రసాదించు, మరియు పునరుత్థాన రోజున మమ్మల్ని అవమానించవద్దు. నిశ్చయంగా నీవు నీ వాగ్దానాన్ని ఉల్లంఘించవు.", "పునరుత్థాన రోజున అవమానానికి శరణాగతి పొందండి.", "పరలోకంలో గౌరవం కోరుతూ."),
        "dua_q_israfana" to DuaText("మా మితిమీరిన పనులను క్షమించండి", "మా ప్రభూ, మా పాపాలను, మా వ్యవహారాలలో మా మితిమీరిన చర్యలను మాకు క్షమించండి, మా పాదాలను దృఢపరచండి, అవిశ్వాసులకు వ్యతిరేకంగా మాకు సహాయం చేయండి.", "మునుపటి ప్రవక్తల సహచరుల దుఆ.", "స్థిరత్వం మరియు క్షమాపణ కోసం ఒక దుఆ."),
        "dua_q_jamiun_nas" to DuaText("మీరు మానవజాతిని సమీకరిస్తారు", "మా ప్రభూ, మీరు నిస్సందేహంగా ఎటువంటి సందేహం లేని రోజున మానవులను సమీకరిస్తారు. నిశ్చయంగా అల్లాహ్ తన వాగ్దానాన్ని ఉల్లంఘించడు.", "పునరుత్థాన దినాన నిశ్చయంగా ధృవీకరించడం.", "జ్ఞానంలో దృఢంగా ఆధారపడిన వారి ద్వయం."),
        "dua_q_maash_shahidin" to DuaText("సాక్షుల మధ్య మాకు వ్రాయండి", "మా ప్రభూ, మేము విశ్వసించాము, కాబట్టి మమ్మల్ని సాక్షుల మధ్య వ్రాయండి.", "సత్యాన్ని గుర్తించి, విశ్వసించే వారి దుఆ.", "ఒకరి విశ్వాసాన్ని అంగీకరించడానికి ఒక దుఆ."),
        "dua_q_la_tajalna_zalimin" to DuaText("తప్పు చేసిన వారితో కాదు", "మా ప్రభూ, మమ్మల్ని అన్యాయస్థులైన వ్యక్తులతో కలిసి ఉంచవద్దు.", "అల్-అరాఫ్ ప్రజల దుఆ.", "తప్పు చేసిన వారి విధి నుండి శరణాగతి పొందండి."),
        "dua_q_tawaffana_muslimin" to DuaText("ముస్లింలుగా సహనం మరియు మరణం", "మా ప్రభూ, మాపై సహనం వహించండి మరియు మమ్మల్ని ముస్లింలుగా చనిపోయేలా చేయండి.", "వారు విశ్వసించినప్పుడు ఫరో మంత్రగత్తెల దుఆ.", "విచారణలో సహనం మరియు విశ్వాసంపై ముగింపు."),
        "dua_q_la_tajalna_fitnah" to DuaText("అణచివేతదారులకు విచారణ కాదు", "మేము అల్లాహ్పై ఆధారపడతాము. మా ప్రభూ, మాకు అన్యాయస్థులైన ప్రజలకు శిక్షను విధించవద్దు, మరియు నీ దయ ద్వారా అవిశ్వాసుల నుండి మమ్మల్ని రక్షించుము.", "మూసా (ఏఎస్) ప్రజల దుఆ.", "అణచివేత మరియు అణచివేతదారుల నుండి రక్షించడానికి ఒక దుఆ."),
        "dua_q_nuh_ma_laysa_li" to DuaText("క్షమాపణ కోసం నూహ్ (అ. స.) యొక్క దువా", "నా ప్రభూ, నాకు తెలియని దాని కోసం నిన్ను అడగకుండా నేను నీలో ఆశ్రయం కోరుతున్నాను. మరియు నీవు నన్ను క్షమించి, నన్ను కరుణించకపోతే, నేను నష్టపోయేవారిలో ఒకడిని అవుతాను.", "ప్రవక్త నూహ్ (అ. స.) యొక్క పశ్చాత్తాపానికి సంబంధించిన దుఆ.", "సరైన పద్ధతిలో అడగడంలో ఒక పాఠం."),
        "dua_q_mudkhala_sidq" to DuaText("సత్యం యొక్క ప్రవేశం మరియు నిష్క్రమణ", "నా ప్రభూ, నన్ను సత్యంతో ప్రవేశింపజేయండి, సత్యంతో నిష్క్రమించండి, మరియు మీ నుండి నాకు సహాయక అధికారాన్ని ఇవ్వండి.", "కొత్త పనిలోకి ప్రవేశించే ముందు, ఇల్లు లేదా ప్రదేశం.", "హిజ్రా సమయంలో ఈ దుఆ ప్రవక్తకు సలీం సల్లల్లాహు అలైహి వసల్లం బోధించింది."),
        "dua_q_la_tadharni_fardan" to DuaText("జకారియా (ఏఎస్) యొక్క దువా-నన్ను ఒంటరిగా వదిలివేయవద్దు", "నా ప్రభూ, నన్ను ఒంటరిగా వదిలివేయవద్దు, అప్పుడు నీవు ఉత్తమ వారసులు.", "పిల్లలు కోరుకునే వారి కోసం.", "ఈ దుఆ ద్వారా అల్లాహ్ యాహ్యా (అస్) ను మంజూరు చేశాడు."),
        "dua_q_munzalan_mubarakan" to DuaText("ఒక పవిత్రమైన ల్యాండింగ్ స్థలం", "నా ప్రభూ, నన్ను ఒక ఆశీర్వదించబడిన ల్యాండింగ్ ప్రదేశంలో దిగడానికి అనుమతించండి, మరియు మీరు భూమిని తీసుకువచ్చేవారిలో ఉత్తమమైనవారు.", "కొత్త ఇంటికి వెళ్ళేటప్పుడు లేదా ఎక్కడో ఆగేటప్పుడు-నూహ్ (AS) యొక్క దుఆ.", "కొత్త ప్రదేశంలో ఆశీర్వాదం కోసం ఒక దుఆ."),
        "dua_q_amanna_faghfir" to DuaText("మేము నమ్ముతాము, కాబట్టి మమ్మల్ని క్షమించండి.", "మా ప్రభూ, మేము విశ్వసించాము, కాబట్టి మమ్మల్ని క్షమించండి మరియు మమ్మల్ని కరుణించండి, మరియు మీరు దయగలవారిలో ఉత్తములు.", "అల్లాహ్ యొక్క నీతిమంతులైన సేవకుల దుఆ.", "క్షమాపణ మరియు దయ కోసం సమగ్ర దుఆ."),
        "dua_q_isrif_jahannam" to DuaText("నరక శిక్షను నివారించండి", "మా ప్రభూ, నరక శిక్షను మా నుండి తప్పించుకోండి. నిశ్చయంగా దాని శిక్ష నిరంతరం కొనసాగుతుంది. నిశ్చయంగా అది ఒక చెడు నివాసం, నివాసం.", "అత్యంత కరుణామయుడు ('ఇబ్ద్ అర్-రెహమాన్) యొక్క సేవకుల దుఆ.", "నరకం నుండి ఆశ్రయం కోసం ఖురాన్ దుఆ."),
        "dua_q_hab_li_hukman" to DuaText("ఇబ్రహీం (అ. స.) యొక్క దువా-వివేకం మరియు జన్నా", "నా ప్రభూ, నాకు జ్ఞానాన్ని ప్రసాదించండి మరియు నీతిమంతులతో నాతో చేరండి, తరువాతి తరాలలో నాకు గౌరవప్రదమైన ప్రస్తావనను ఇవ్వండి మరియు నన్ను ఆనంద ఉద్యానవన వారసులలో ఒకరిగా చేయండి.", "జ్ఞానం కోసం అడగడం, నీతిమంతుల మరియు స్వర్గం యొక్క సంస్థ.", "ఇబ్రహీం (అ. స.) యొక్క సమగ్ర దుఆ."),
        "dua_q_lut_najjini_ahli" to DuaText("లూత్ (ఏఎస్) యొక్క దువా-సేవ్ మై ఫ్యామిలీ", "నా ప్రభూ, నన్ను మరియు నా కుటుంబాన్ని వారు చేసే (పరిణామం) నుండి రక్షించండి.", "ఒకరి కుటుంబాన్ని చెడు వాతావరణం నుండి రక్షించడం.", "చెడు నుండి కుటుంబాన్ని రక్షించండి."),
        "dua_q_sulaiman_awzini" to DuaText("కృతజ్ఞత కోసం సులేమాన్ (ఏఎస్) దువా", "నా ప్రభూ, నీవు నాకు, నా తల్లిదండ్రులకు ఇచ్చిన అనుగ్రహానికి కృతజ్ఞతతో ఉండటానికి, నీకు సంతోషాన్నిచ్చే మంచి పనులు చేయడానికి, నీ దయ ద్వారా నన్ను నీ నీతిమంతుడైన సేవకులలో చేర్చడానికి నాకు వీలు కల్పించు.", "ఆశీర్వాదాలకు కృతజ్ఞతతో ఉండగల సామర్థ్యం కోసం.", "సులేమాన్ (ఏఎస్) యొక్క కృతజ్ఞత యొక్క దుఆ."),
        "dua_q_musa_zalamtu" to DuaText("మూసా (అ. స.) యొక్క దువా-నేను నాకు నేనే అన్యాయం చేసుకున్నాను", "నా ప్రభూ, నాకు నేను అన్యాయం చేశాను, కాబట్టి నన్ను క్షమించండి.", "పొరపాటు తర్వాత వెంటనే పశ్చాత్తాపం.", "అల్లాహ్ మూసాను (అ. స.) క్షమించాడు."),
        "dua_q_musa_najjini" to DuaText("మూసా (అ. స.) యొక్క దువా-నన్ను అణచివేసేవారి నుండి రక్షించండి", "నా ప్రభూ, అన్యాయస్థుల నుండి నన్ను రక్షించు.", "అణచివేతదారులకు భయపడినప్పుడు.", "ఈజిప్టు నుండి బయలుదేరినప్పుడు మూసా (AS) యొక్క దుఆ."),
        "dua_q_lut_unsurni" to DuaText("లూత్ (ఏఎస్) యొక్క దువా-అవినీతిపరులపై సహాయం", "నా ప్రభూ, అవినీతిపరులైన ప్రజల నుండి నాకు సహాయం చెయ్యండి.", "అవినీతిని వ్యాప్తి చేసే వారికి వ్యతిరేకంగా సహాయం కోసం.", "సత్యంపై దృఢంగా నిలబడే వారి ద్వయం."),
        "dua_q_hab_li_salihin" to DuaText("నీతిమంతుడైన బిడ్డ కోసం ఇబ్రహీం (అ. స.) యొక్క దువా", "నా ప్రభూ, నాకు (ఒక బిడ్డను) నీతిమంతుల నుండి ప్రసాదించండి.", "నీతిమంతులైన పిల్లలను అడగడం.", "దీని ద్వారా దుఆ ఇస్మాయిల్ (ఎఎస్) మంజూరు చేయబడింది."),
        "dua_q_wasita_kulla_shay" to DuaText("సింహాసనాన్ని మోస్తున్న దూతల దువా", "మా ప్రభూ, నీవు దయతో మరియు జ్ఞానంతో అన్ని విషయాలను చుట్టుముట్టావు, కాబట్టి పశ్చాత్తాపపడి, నీ మార్గాన్ని అనుసరించేవారిని క్షమించండి మరియు వారిని నరకం శిక్ష నుండి రక్షించండి.", "సింహాసనాన్ని మోసుకెళ్లే దేవదూతలు విశ్వాసుల కోసం ఈ దుఆ చేస్తారు.", "దేవతల దుఆలో చేర్చాలనే ఉద్దేశ్యంతో పఠించారు."),
        "dua_q_ikhwanina" to DuaText("మనకు ముందు ఉన్న మన సోదరుల కోసం", "మా ప్రభూ, మాకు మరియు మాకు ముందు విశ్వాసంలో ఉన్న మా సోదరులకు క్షమాపణలు చెప్పు, మరియు విశ్వసించే వారి పట్ల మా హృదయాలలో కోపం కలిగించకండి. మా ప్రభూ, నీవు నిశ్చయంగా దయగలవాడవు, దయగలవాడవు.", "ముందు వచ్చిన విశ్వాసులకు మరియు స్వచ్ఛమైన హృదయం కోసం ఒక దుఆ.", "గొప్ప సహచరులు (ఆర్ఏ) మరియు మునుపటి విశ్వాసులకు ఒక దుఆ."),
        "dua_q_alayka_tawakkalna" to DuaText("మేము మీపై ఆధారపడతాము (ఇబ్రహీం అ. స.)", "మా ప్రభూ, మేము నీపైనే ఆధారపడతాము, మేము నీ వైపు మొగ్గు చూపుతాము, మరియు నీ వైపు తిరిగి వస్తాము. మా ప్రభూ, మాకు అవిశ్వాసులకు పరీక్షగా మార్చవద్దు, మమ్మల్ని క్షమించుము. మా ప్రభూ, నీవు నిశ్చయంగా సర్వశక్తిమంతుడవు, వివేకుడవు.", "ఇబ్రహీం (అ. స.) మరియు అతని సహచరుల దుఆ.", "అల్లాహ్ మీద ఆధారపడటం మరియు ఆయన వైపు తిరగడం."),
        "dua_q_atmim_nurana" to DuaText("మన వెలుగు పరిపూర్ణం", "మా ప్రభూ, మా వెలుగు మాకు పరిపూర్ణం చేసి, మమ్మల్ని క్షమించు. నిశ్చయంగా నీకు అన్నింటిపై అధికారం ఉంది.", "పునరుత్థాన రోజున విశ్వాసుల దుఆ.", "సిరత్ మీద వెలుగు కోసం అడుగుతోంది."),
        "dua_q_asiya_baytan" to DuaText("ఆసియా దుఆ-జన్నాలోని ఒక ఇల్లు", "నా ప్రభూ, నీ దగ్గర స్వర్గంలో నాకు ఒక మందిరాన్ని నిర్మించు, ఫరో నుండి, అతని పనుల నుండి నన్ను రక్షించు, అన్యాయస్థుల నుండి నన్ను రక్షించు.", "ఫరోకు భార్య అయిన ఆసియా యొక్క దుఆ.", "అల్లాహ్ ఆమెను విశ్వాసులకు ఒక ఉదాహరణగా చేశాడు."),
        "dua_adhan_response" to DuaText("అధాన్కు ప్రతిస్పందించడం", "అల్లాహ్ వద్ద తప్ప శక్తి, శక్తి ఏమీ లేవు.", "'హయ్యా'అలాస్-సలాహ్'మరియు'హయ్యా'అలాల్-ఫలాహ్'వద్ద ముయిజిన్ చెప్పిన దాన్ని పునరావృతం చేయండి.", "హృదయపూర్వకంగా స్పందించే వారు స్వర్గంలోకి ప్రవేశిస్తారు."),
        "dua_adhan_shahadah" to DuaText("ముఅజ్జీన్ షహాదా తరువాత", "అల్లాహ్ తప్ప, ఒంటరిగా, భాగస్వామి లేకుండా, ఆరాధించబడే హక్కు ఎవరికీ లేదని, ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం ఆయన సేవకుడు, ప్రవక్త అని నేను కూడా సాక్ష్యమిస్తున్నాను. అల్లాహ్ పట్ల నేను సంతృప్తి చెందాను, ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం ప్రవక్తగా, ఇస్లాం మతాన్ని మతంగా కలిగి ఉన్నాను.", "ముయెజ్జీన్ విశ్వాసం గురించి సాక్ష్యం విన్నప్పుడు.", "ఆయన చేసిన పాపాలు క్షమించబడతాయి."),
        "dua_istiftah_baid" to DuaText("దువాను తెరవడంః పాపాల నుండి నన్ను దూరం చేయండి", "ఓ అల్లాహ్, తూర్పును పశ్చిమం నుండి దూరం చేసినందున నా పాపాల నుండి నన్ను దూరం చేయి. ఓ అల్లాహ్, తెల్లటి వస్త్రం మురికి నుండి శుద్ధి చేయబడినట్లుగా నన్ను పాపాల నుండి శుద్ధి చేయి. ఓ అల్లాహ్, నా పాపాలను నీరు, మంచు మరియు వడగళ్ళతో కడిగివేయండి.", "ప్రారంభ తక్బీర్ తరువాత (సనా స్థానంలో కూడా చెప్పవచ్చు).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తక్బీర్ మరియు పారాయణ మధ్య దీనిని పారాయణ చేశారు."),
        "dua_hamdan_kathiran" to DuaText("రుకు తర్వాత సమృద్ధిగా ప్రశంసలు", "మా ప్రభూ, నీకు స్తుతి ఉంది-సమృద్ధిగా, స్వచ్ఛంగా మరియు ఆశీర్వదించబడిన ప్రశంస.", "రుకు నుండి లేచిన తరువాత,'రబ్బానా లాకల్-హమ్ద్'తో కలిసి.", "ముప్పై మందికి పైగా దేవుళ్ళు దీనిని రికార్డ్ చేసిన మొదటి వ్యక్తిగా పోటీ పడ్డారు."),
    )
}
